// src/ui/guardian-modal.ts
var import_obsidian5 = require("obsidian");
var GuardianModal = class extends import_obsidian5.Modal {
  result;
  onSubmit;
  constructor(app, onSubmit) {
    super(app);
    this.onSubmit = onSubmit;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.createEl("h2", { text: "Guardian Manual Trigger" });
    new import_obsidian5.Setting(contentEl).setName("Instruction").setDesc("What should I do with the current context?").addText((text) => text.setPlaceholder("e.g. Translate to English, Summarize, Fix grammar...").setValue("").onChange((value) => {
      this.result = value;
    }).inputEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        this.submit();
      }
    }));
    new import_obsidian5.Setting(contentEl).addButton((btn) => btn.setButtonText("Submit").setCta().onClick(() => {
      this.submit();
    }));
  }
  submit() {
    if (!this.result) {
      new import_obsidian5.Notice("Please enter an instruction.");
      return;
    }
    this.close();
    this.onSubmit(this.result);
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};

// src/ui/selection-menu.ts
var import_obsidian6 = require("obsidian");
var import_view3 = require("@codemirror/view");
var import_state5 = require("@codemirror/state");
var globalActionCallback = null;
function setSelectionActionCallback(callback) {
  globalActionCallback = callback;
}
var pluginApp = null;
var setSelectionMenuState = import_state5.StateEffect.define();
var selectionMenuField = import_state5.StateField.define({
  create() {
    return { type: "hidden" };
  },
  update(state, tr) {
    for (let effect of tr.effects) {
      if (effect.is(setSelectionMenuState)) {
        return effect.value;
      }
    }
    if (tr.selection) {
      const selection = tr.newSelection.main;
      if (selection.empty) {
        return { type: "hidden" };
      }
      if (state.type !== "hidden" && (selection.from !== state.from || selection.to !== state.to)) {
        return { type: "button", from: selection.from, to: selection.to };
      }
      if (state.type === "hidden") {
        return { type: "button", from: selection.from, to: selection.to };
      }
    }
    return state;
  },
  provide: (f) => import_view3.showTooltip.from(f, (state) => {
    if (state.type === "hidden")
      return null;
    return {
      pos: state.from,
      above: true,
      strictSide: true,
      create: (view) => {
        const dom = document.createElement("div");
        dom.className = "guardian-selection-tooltip";
        if (state.type === "button") {
          const btn = document.createElement("button");
          btn.className = "guardian-selection-btn";
          btn.textContent = "Comment / AI";
          btn.onclick = () => {
            view.dispatch({
              effects: setSelectionMenuState.of({ type: "input", from: state.from, to: state.to })
            });
          };
          dom.appendChild(btn);
        } else if (state.type === "input") {
          const wrapper = document.createElement("div");
          wrapper.className = "guardian-input-wrapper";
          const textarea = document.createElement("textarea");
          textarea.placeholder = "Ask AI to edit...";
          textarea.className = "guardian-selection-input";
          textarea.onkeydown = (e) => {
            e.stopPropagation();
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              const text = textarea.value.trim();
              if (text && globalActionCallback) {
                view.dispatch({
                  effects: setSelectionMenuState.of({ type: "processing", from: state.from, to: state.to })
                });
                globalActionCallback(view, { from: state.from, to: state.to }, text);
              }
            }
            if (e.key === "Escape") {
              e.preventDefault();
              view.dispatch({
                effects: setSelectionMenuState.of({ type: "button", from: state.from, to: state.to })
              });
            }
          };
          const btnGroup = document.createElement("div");
          btnGroup.className = "guardian-btn-group";
          const submitBtn = document.createElement("button");
          submitBtn.textContent = "Submit";
          submitBtn.className = "guardian-submit-btn";
          submitBtn.onclick = () => {
            const text = textarea.value.trim();
            if (text && globalActionCallback) {
              view.dispatch({
                effects: setSelectionMenuState.of({ type: "processing", from: state.from, to: state.to })
              });
              globalActionCallback(view, { from: state.from, to: state.to }, text);
            }
          };
          btnGroup.appendChild(submitBtn);
          wrapper.appendChild(textarea);
          wrapper.appendChild(btnGroup);
          dom.appendChild(wrapper);
          setTimeout(() => textarea.focus(), 20);
        } else if (state.type === "processing") {
          dom.textContent = "Thinking...";
          dom.className += " guardian-processing";
        } else if (state.type === "result") {
          const wrapper = document.createElement("div");
          wrapper.className = "guardian-result-view";
          const content = document.createElement("div");
          content.className = "guardian-result-content";
          if (pluginApp) {
            import_obsidian6.MarkdownRenderer.render(pluginApp, state.content, content, "", new import_obsidian6.Component());
          } else {
            content.textContent = state.content;
          }
          wrapper.appendChild(content);
          setTimeout(() => {
            content.scrollTop = 0;
          }, 0);
          const actions = document.createElement("div");
          actions.className = "guardian-result-actions";
          const copyBtn = document.createElement("button");
          copyBtn.textContent = "Copy";
          copyBtn.onclick = () => {
            navigator.clipboard.writeText(state.content);
            copyBtn.textContent = "Copied!";
            setTimeout(() => copyBtn.textContent = "Copy", 2e3);
          };
          const closeBtn = document.createElement("button");
          closeBtn.textContent = "Close";
          closeBtn.onclick = () => {
            view.dispatch({
              effects: setSelectionMenuState.of({ type: "hidden" })
            });
          };
          actions.appendChild(copyBtn);
          actions.appendChild(closeBtn);
          wrapper.appendChild(actions);
          dom.appendChild(wrapper);
        }
        return { dom };
      }
    };
  })
});
function selectionMenuExtension(app) {
  pluginApp = app;
  return [
    selectionMenuField
  ];
}
function resetSelectionMenu(view) {
  view.dispatch({
    effects: setSelectionMenuState.of({ type: "hidden" })
  });
}

// main.ts
var GeminiShellPlugin = class extends import_obsidian7.Plugin {
  settings;
  geminiApi;
  toolManager;
  // Debounce with trailing edge (default/false) for inactivity trigger
  onEditorChangeDebounced = (0, import_obsidian7.debounce)(this.runGuardianCheck.bind(this), 3e3);
  async onload() {
    await this.loadSettings();
    new import_obsidian7.Notice("Gemini Shell: Plugin Loaded (v2)");
    this.toolManager = new ToolManager(this.app, this.settings.allowPluginControl);
    this.geminiApi = new GeminiAPI(this.app, this.settings, this.toolManager);
    this.registerView(
      VIEW_TYPE_GEMINI_SHELL,
      (leaf) => new GeminiShellView(leaf, this.geminiApi)
    );
    this.addRibbonIcon("terminal", "Open Gemini Shell", (evt) => {
      this.activateView();
    });
    this.addCommand({
      id: "open-gemini-shell",
      name: "Open Shell",
      callback: () => this.activateView(),
      hotkeys: [{ modifiers: ["Mod"], key: "j" }]
    });
    this.addCommand({
      id: "guardian-manual-trigger",
      name: "Guardian: Manual Trigger",
      callback: () => this.activateGuardianModal(),
      hotkeys: [{ modifiers: ["Mod", "Shift"], key: "g" }]
    });
    this.addSettingTab(new GeminiShellSettingTab(this.app, this));
    this.registerEditorExtension([
      guardianGutterExtension(),
      ghostTextExtension(),
      selectionMenuExtension(this.app)
    ]);
    setSelectionActionCallback(this.runGuardianSelectionAction.bind(this));
    this.registerEvent(
      this.app.workspace.on("editor-change", this.onEditorChangeDebounced)
    );
    this.registerEvent(
      this.app.vault.on("modify", (file) => {
        if (file instanceof import_obsidian7.TFile && file.extension === "md") {
          this.onFileModify(file);
        }
      })
    );
  }
  async activateView() {
    const { workspace } = this.app;
    const leaves = workspace.getLeavesOfType(VIEW_TYPE_GEMINI_SHELL);
    if (leaves.length > 0) {
      leaves[0].detach();
    } else {
      const leaf = workspace.getRightLeaf(false);
      await leaf?.setViewState({ type: VIEW_TYPE_GEMINI_SHELL, active: true });
      workspace.revealLeaf(leaf);
    }
  }
  activateGuardianModal() {
    const view = this.app.workspace.getActiveViewOfType(import_obsidian7.MarkdownView);
    if (!view) {
      new import_obsidian7.Notice("Please open a Markdown file first.");
      return;
    }
    new GuardianModal(this.app, (instruction) => {
      this.runGuardianCheck(view.editor, null, instruction);
    }).open();
  }
  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }
  async saveSettings() {
    await this.saveData(this.settings);
    this.toolManager = new ToolManager(this.app, this.settings.allowPluginControl);
    this.geminiApi = new GeminiAPI(this.app, this.settings, this.toolManager);
  }
  // Handle Manual Selection Action
  async runGuardianSelectionAction(view, selection, instruction) {
    const selectedText = view.state.doc.sliceString(selection.from, selection.to);
    const startLine = view.state.doc.lineAt(selection.from).number;
    const contextStart = Math.max(1, startLine - 5);
    const contextEnd = Math.min(view.state.doc.lines, startLine + 5);
    const contextLines = [];
    for (let i = contextStart; i <= contextEnd; i++) {
      contextLines.push(view.state.doc.line(i).text);
    }
    const contextText = contextLines.join("\n");
    const prompt = `User Instruction: "${instruction}"
Selected Text: "${selectedText}"
Context:
"${contextText}"

Task: Execute the user's instruction on the selected text.
- If the user wants to edit/rewrite/translate the text, return JSON: {"type":"edit", "suggestion":"REPLACED_TEXT"}
- If the user asks a question, return JSON: {"type":"answer", "suggestion":"ANSWER_TEXT"}
- Ensure the suggestion uses proper Markdown formatting.
- Return ONLY JSON.`;
    try {
      const response = await this.geminiApi.chat(prompt, "GuardianSelection", "You are a helpful assistant. Return ONLY JSON.");
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const data = JSON.parse(jsonMatch[0]);
        if (data.type === "edit" && data.suggestion) {
          const line = view.state.doc.lineAt(selection.from).number;
          const ch = selection.from - view.state.doc.line(line).from;
          showGhostText(view, data.suggestion, line, ch, { from: selection.from, to: selection.to });
          resetSelectionMenu(view);
        } else if (data.type === "answer") {
          view.dispatch({
            effects: setSelectionMenuState.of({
              type: "result",
              from: selection.from,
              to: selection.to,
              content: data.suggestion
            })
          });
        } else {
          new import_obsidian7.Notice("Guardian: No action taken.");
          resetSelectionMenu(view);
        }
      } else {
        new import_obsidian7.Notice("Guardian: Failed to parse response.");
        resetSelectionMenu(view);
      }
    } catch (error) {
      console.error("Guardian Selection Error:", error);
      new import_obsidian7.Notice("Guardian Error: " + error.message);
      resetSelectionMenu(view);
    }
  }
  async onFileModify(file) {
    if (file.path !== this.settings.wechatInboxPath)
      return;
    const content = await this.app.vault.read(file);
    const regex = /(\[\[.*?\]\])|(\[.*?\]\(.*?\))|(https?:\/\/[^\s\)]+)/g;
    let newContent = content;
    let modified = false;
    const rawUrlMatches = [];
    for (const m of content.matchAll(regex)) {
      if (!m[1] && !m[2] && m[3]) {
        rawUrlMatches.push({
          url: m[3],
          index: m.index,
          length: m[0].length
        });
      }
    }
    if (rawUrlMatches.length === 0)
      return;
    rawUrlMatches.sort((a, b) => b.index - a.index);
    for (const m of rawUrlMatches) {
      new import_obsidian7.Notice(`\u{1F4E5} Auto-saving: ${m.url}`);
      const result = await this.toolManager.execute("save_webpage", { url: m.url });
      if (result.success) {
        let finalPath = result.path;
        if (this.settings.wechatStoragePath) {
          const folder = this.settings.wechatStoragePath;
          if (!await this.app.vault.adapter.exists(folder)) {
            await this.app.vault.createFolder(folder);
          }
          const fileName = finalPath.split("/").pop();
          const newPath = `${folder}/${fileName}`;
          let targetPath = newPath;
          let counter = 1;
          while (await this.app.vault.adapter.exists(targetPath)) {
            targetPath = `${folder}/${fileName.replace(".md", "")} (${counter}).md`;
            counter++;
          }
          const fileToMove = this.app.vault.getAbstractFileByPath(finalPath);
          if (fileToMove) {
            await this.app.vault.rename(fileToMove, targetPath);
            finalPath = targetPath;
          }
        }
        const linkText = `[[${finalPath}|Saved: ${finalPath.split("/").pop()?.replace(".md", "")}]]`;
        newContent = newContent.substring(0, m.index) + linkText + newContent.substring(m.index + m.length);
        modified = true;
      } else {
        new import_obsidian7.Notice(`\u274C Failed to save ${m.url}: ${result.error}`);
      }
    }
    if (modified) {
      await this.app.vault.modify(file, newContent);
    }
  }
  async runGuardianCheck(editor, info, manualInstruction) {
    if (!this.settings.enableGuardian)
      return;
    if (!manualInstruction && !this.settings.guardianAutoMode)
      return;
    const cursor = editor.getCursor();
    const lineNumber = cursor.line + 1;
    const view = editor.cm;
    if (!view)
      return;
    const isGuardianEnabled = view.state.field(guardianModeField);
    if (!manualInstruction && !isGuardianEnabled)
      return;
    const line = editor.getLine(cursor.line);
    if (!manualInstruction && (!line.trim() || line.trim().length < 3))
      return;
    const startLine = Math.max(0, cursor.line - 10);
    const contextLines = [];
    for (let i = startLine; i <= cursor.line; i++) {
      contextLines.push(editor.getLine(i));
    }
    const contextText = contextLines.join("\n");
    updateGuardianState(view, lineNumber, "thinking" /* Thinking */);
    try {
      let prompt = "";
      let systemPromptOverride = "";
      if (manualInstruction) {
        prompt = `User Instruction: "${manualInstruction}"
Context:
"${contextText}"

Please execute the instruction.
- If it's an edit, return JSON: {"type":"edit", "suggestion":"REPLACED_TEXT"}
- If it's a question, return JSON: {"type":"answer", "suggestion":"ANSWER_TEXT"}
- If no action needed, return JSON: {"type":"none"}
- Ensure the suggestion uses proper Markdown formatting.`;
        systemPromptOverride = "You are a helpful assistant. Return ONLY JSON.";
      } else {
        prompt = `Role: ${this.settings.systemPrompt || "You are a helpful AI assistant."}
Task: You are a helpful co-writer. Complete the user's thought or continue the text naturally.

Context:
${contextText}

Instructions:
1. Suggest a continuation that flows naturally based on the context.
2. Do NOT repeat the input text.
3. If the text is complete or you have no good suggestion, return "type": "none".
4. Output JSON: {"type": "completion", "suggestion": "MARKDOWN_FORMATTED_TEXT"}
5. Ensure the suggestion uses proper Markdown formatting (bold, italic, lists, code blocks) where appropriate.`;
      }
      const response = await this.geminiApi.chat(prompt, "Guardian", systemPromptOverride);
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (!jsonMatch) {
        updateGuardianState(view, lineNumber, "idle" /* Idle */);
        return;
      }
      const data = JSON.parse(jsonMatch[0]);
      if (data.suggestion && typeof data.suggestion === "string") {
        const currentLineCount = view.state.doc.lines;
        if (lineNumber > currentLineCount) {
          console.warn("Guardian: Line number out of bounds after generation.");
          updateGuardianState(view, lineNumber, "idle" /* Idle */);
          return;
        }
        const currentLine = view.state.doc.line(lineNumber);
        const safeCh = Math.min(cursor.ch, currentLine.length);
        console.log("Guardian: Showing ghost text", { suggestion: data.suggestion, line: lineNumber, ch: safeCh });
        showGhostText(view, data.suggestion, lineNumber, safeCh);
        updateGuardianState(view, lineNumber, "has-suggestion" /* HasSuggestion */);
      } else {
        updateGuardianState(view, lineNumber, "idle" /* Idle */);
      }
      if (data.type === "none") {
        updateGuardianState(view, lineNumber, "idle" /* Idle */);
        return;
      }
    } catch (error) {
      console.error("Guardian Error:", error);
      updateGuardianState(view, lineNumber, "error" /* Error */);
    }
  }
};
